    "home.sign_in": "Injira",
    "home.title": "Cunga iduka cyangwa ubucuruzi bw'imodoka ahantu hamwe",
    "home.subtitle": "Higoverse yandika ibicuruzwa, ibyagurishijwe, ibyaguzwe, amafaranga yasohotse, amadeni y'abakiriya, proforma n'imishahara, ikakwereka uko ubucuruzi buhagaze: kuri murandasi, kuri Android no kuri Windows.",
    "home.get_account": "Bona konti",
    "home.available_on": "Iboneka kuri",
    "home.platform_web": "Urubuga",
    "home.platform_android": "Porogaramu ya Android",
    "home.platform_windows": "Porogaramu ya Windows",
    "home.version": "Verisiyo {v}",
    "home.open": "Fungura",
    "home.download": "Kuramo",
    "home.languages": "Mu Cyongereza, Ikinyarwanda, Igifaransa, Igiswahili n'Igishinwa. Buri wese ahitamo urwe.",
    "home.features_title": "Ibyo ubucuruzi bwawe bwandika byose, ahantu hamwe",
    "home.features_sub": "Konti imwe ku rubuga, kuri telefoni no kuri mudasobwa, ihita ivugururwa kuri buri wese mu itsinda.",
    "home.f_stock": "Ibicuruzwa n'ububiko",
    "home.f_stock_text": "Buri gicuruzwa cyangwa imodoka n'igiciro n'umubare wacyo, n'imenyesha mbere y'uko bishira.",
    "home.f_sales": "Ibyagurishijwe",
    "home.f_sales_text": "Andika igurisha mu masegonda, ryishyuwe ryose cyangwa hasigaye umwenda, urebe ibyagurishijwe uyu munsi.",
    "home.f_purchases": "Ibyaguzwe n'abatanga ibicuruzwa",
    "home.f_purchases_text": "Ongera ububiko uvuye ku batanga ibicuruzwa; ububiko bwivugurura kandi buri cyinjiye kigumana igiciro cyacyo.",
    "home.f_expenses": "Amafaranga yasohotse",
    "home.f_expenses_text": "Ubukode, ingendo, amazi n'amashanyarazi n'ibindi, buri kimwe n'uko cyishyuwe n'ifoto y'inyemezabwishyu.",
    "home.f_debts": "Amadeni y'abakiriya",
    "home.f_debts_text": "Uwo ufitiye umwenda n'angahe, buri bwishyu uko buje, na nimero ya telefoni y'umukiriya hafi.",
    "home.f_proforma": "Proforma",
    "home.f_proforma_text": "Proforma nziza za A4 zifite ikirango cyawe n'amakuru ya banki, zemezwa na nyir'ubucuruzi, zigahinduka igurisha iyo umukiriya aguze.",
    "home.f_payroll": "Imishahara",
    "home.f_payroll_text": "Imishahara ya buri kwezi n'ibikurwaho, n'icyemezo cyo kwishyurwa buri mukozi asinyaho.",
    "home.f_reports": "Raporo",
    "home.f_reports_text": "Ibyinjiye, ibyasohotse, inyungu, ibigurishwa cyane n'agaciro k'ububiko, umunsi ku wundi n'ukwezi ku kundi.",
    "home.f_team": "Itsinda ryawe",
    "home.f_team_text": "Abakozi bahabwa uburyo bwabo bwo kwinjira, buri wese akabona gusa ibyo umwanya we wemera.",
    "home.f_messages": "Ubutumwa n'imenyesha",
    "home.f_messages_text": "Vugana n'itsinda ryawe muri Higoverse, umenyeshwe igurisha, amande n'ibicuruzwa bigiye gushira bikimara kuba.",
    "home.cars_title": "Ku bacuruza imodoka",
    "home.cars_sub": "Buri modoka ni imodoka imwe, ikurikiranwa kuva igeze kugeza ihererekanyijwe.",
    "home.cars_1": "Injiza imodoka nyinshi icyarimwe (10 BYD Yuan Up, 20 Neta U Pro), hanyuma uhe buri imwe nimero ya chassis na purake.",
    "home.cars_2": "Imodoka zitondekanye ku izina, ugaragaza iziboneka, izitegereje ihererekanya n'izagurishijwe.",
    "home.cars_3": "Avansi n'ibisigaye kuri buri muguzi, n'amande y'imodoka abikwa kugeza ihererekanyijwe.",
    "home.cars_4": "Proforma z'imodoka zifite chassis, purake na konti ya banki yawe, ziteguye gusohorwa.",
    "home.shops_title": "Ku maduka",
    "home.shops_sub": "Menya ibyo ufite, ibigurishwa n'ibyo ugomba kurangura, utabaze n'intoki.",
    "home.shops_1": "Ibicuruzwa bike cyangwa byashize bigaragara mbere, ukarangura ukanze rimwe.",
    "home.shops_2": "Ibyaguzwe ku batanga ibicuruzwa byiyongera mu bubiko ubwabyo.",
    "home.shops_3": "Ibyagurishijwe ku mwenda bikurikiranwa nk'amadeni y'abakiriya kugeza yishyuwe.",
    "home.shops_4": "Amafoto, ibiciro n'inyungu kuri buri gicuruzwa, no kwinjiza ukoresheje Excel kugira ngo utangire vuba.",
    "home.start_title": "Uko watangira",
    "home.start_1": "Twandikire",
    "home.start_1_text": "Hamagara cyangwa wandikire Higoverse utubwire ubucuruzi bwawe.",
    "home.start_2": "Tugushyiriraho konti",
    "home.start_2_text": "Dushyiraho ubucuruzi bwawe n'uburyo bwawe bwo kwinjira, ku iduka cyangwa ubucuruzi bw'imodoka.",
    "home.start_3": "Tangira kwandika",
    "home.start_3_text": "Ongeramo ibicuruzwa cyangwa imodoka, utumire itsinda ryawe, wandike igurisha rya mbere.",
    "home.privacy_line": "Amakuru yawe ni ay'ubucuruzi bwawe gusa.",
    "home.privacy_link": "Politiki y'ibanga",
    "home.faq_title": "Ibibazo",
    "home.faq1_q": "Higoverse ni iy'abahe?",
    "home.faq1_a": "Amaduka n'ubucuruzi bwo mu Rwanda bugura bukagurisha ibicuruzwa, n'abacuruza imodoka bakeneye gukurikirana buri modoka hakoreshejwe chassis na purake.",
    "home.faq2_q": "Nabona nte konti?",
    "home.faq2_a": "Konti zishyirwaho na Higoverse. Hamagara cyangwa utwandikire dushyireho ubucuruzi bwawe; hanyuma winjire ukoresheje imeyili n'ijambo ry'ibanga.",
    "home.faq3_q": "Abakozi banjye bayikoresha?",
    "home.faq3_a": "Yego. Nyir'ubucuruzi yongeramo abakozi bafite uburyo bwabo bwo kwinjira, buri wese akabona gusa ibyo umwanya we wemera. Ku bacuruza imodoka, abakozi ntibabona inyungu cyangwa ibiciro byaguzwe.",
    "home.faq4_q": "Ikora kuri telefoni na mudasobwa?",
    "home.faq4_a": "Yego. Koresha urubuga muri mushakisha iyo ari yo yose, porogaramu ya Android kuri telefoni, cyangwa iya Windows kuri mudasobwa. Amakuru ni amwe hose.",
    "home.faq5_q": "Ikoresha izihe ndimi?",
    "home.faq5_a": "Icyongereza, Ikinyarwanda, Igifaransa, Igiswahili n'Igishinwa. Buri wese ahitamo ururimi rwe.",
    "home.faq6_q": "Amakuru y'ubucuruzi bwanjye arinzwe?",
    "home.faq6_a": "Yego. Buri bucuruzi bubona gusa amakuru yabwo, n'abakozi bakabona gusa ibyo imyanya yabo yemera. Politiki y'ibanga isobanura ibibikwa n'impamvu.",
    "home.faq_sub": "Ibisubizo bigufi ku bijyanye na konti, abakozi bawe, ibikoresho byawe n'amakuru yawe.",
    "home.faq_more_title": "Ufite ikindi kibazo?",
    "home.faq_more_text": "Tubaze. Dusubiza kuri WhatsApp, kuri telefoni no kuri imeli.",
    "home.faq7_q": "Nshobora kwinjiza ibicuruzwa nsanganywe?",
    "home.faq7_a": "Yego. Kura urupapuro rwa Excel ku rupapuro rw'ibicuruzwa, wuzuzemo ibicuruzwa byawe, hanyuma uyinjize. Urutonde rushobora no kubikwa muri Excel igihe icyo ari cyo cyose.",
    "home.faq8_q": "Muzamfasha gutangira?",
    "home.faq8_a": "Yego. Dutegura ubucuruzi bwawe turi kumwe, kandi ushobora kutuvugisha kuri WhatsApp, kuri telefoni cyangwa kuri imeli igihe ufite ikibazo.",
    "home.contact_title": "Twandikire",
    "home.contact_sub": "Ku bijyanye na konti, kwerekwa uko ikora cyangwa ikindi kibazo kuri Higoverse, hamagara cyangwa utwandikire.",
    "home.location": "Kigali, Rwanda",
    "home.contact_help_1": "Gufungura konti y'iduka cyangwa iy'ubucuruzi bw'imodoka",
