    "home.faq2_a": "Les comptes sont créés par Higoverse. Appelez-nous ou écrivez-nous et nous configurons votre entreprise ; vous vous connectez ensuite avec votre e-mail et votre mot de passe.",
    "home.faq3_q": "Mes employés peuvent-ils l'utiliser ?",
    "home.faq3_a": "Oui. Le propriétaire ajoute des employés avec leur propre connexion, et chacun ne voit que ce que son rôle permet. Chez les concessionnaires, le personnel ne voit ni bénéfices ni coûts.",
    "home.faq4_q": "Fonctionne-t-il sur téléphone et ordinateur ?",
    "home.faq4_a": "Oui. Utilisez le site depuis n'importe quel navigateur, l'application Android sur votre téléphone ou l'application Windows sur votre ordinateur. Vos données sont les mêmes partout.",
    "home.faq5_q": "Quelles langues sont disponibles ?",
    "home.faq5_a": "Anglais, kinyarwanda, français, swahili et chinois. Chaque personne choisit sa langue.",
    "home.faq6_q": "Les données de mon entreprise sont-elles privées ?",
    "home.faq6_a": "Oui. Chaque entreprise ne voit que ses propres données, et les employés seulement ce que leur rôle permet. La politique de confidentialité explique ce qui est conservé et pourquoi.",
    "home.faq_sub": "Des réponses courtes sur les comptes, votre équipe, vos appareils et vos données.",
    "home.faq_more_title": "Une autre question ?",
    "home.faq_more_text": "Posez-la-nous directement. Nous répondons sur WhatsApp, par téléphone et par e-mail.",
    "home.faq7_q": "Puis-je importer les produits que j'ai déjà ?",
    "home.faq7_a": "Oui. Téléchargez le modèle Excel sur la page des produits, remplissez-le avec vos produits et importez le fichier. Les listes peuvent aussi être exportées vers Excel à tout moment.",
    "home.faq8_q": "M'aiderez-vous à démarrer ?",
    "home.faq8_a": "Oui. Nous configurons votre entreprise avec vous, et vous pouvez nous joindre sur WhatsApp, par téléphone ou par e-mail dès que vous avez une question.",
    "home.contact_title": "Parlons-en",
