    "home.features_sub": "Akaunti moja kwenye tovuti, simu na kompyuta yako, inasasishwa papo hapo kwa kila mtu kwenye timu.",
    "home.f_stock": "Hifadhi na bidhaa",
    "home.f_stock_text": "Kila bidhaa au gari pamoja na bei na idadi yake, na tahadhari kabla haijaisha.",
    "home.f_sales": "Mauzo",
    "home.f_sales_text": "Rekodi mauzo kwa sekunde, yaliyolipwa kikamilifu au yenye salio, na uone kilichouzwa leo.",
    "home.f_purchases": "Manunuzi na wasambazaji",
    "home.f_purchases_text": "Jaza hifadhi kutoka kwa wasambazaji; hifadhi inajisasisha na kila mzigo unahifadhi gharama yake.",
    "home.f_expenses": "Gharama",
