    "home.f_debts": "Madeni ya wateja",
    "home.f_debts_text": "Nani anadaiwa kiasi gani, kila malipo yanapoingia, na namba ya simu ya mteja karibu.",
    "home.f_proforma": "Ankara za proforma",
    "home.f_proforma_text": "Proforma safi za A4 zenye nembo yako na taarifa za benki, zinazoidhinishwa na mmiliki na kugeuka mauzo mteja anaponunua.",
    "home.f_payroll": "Mishahara",
    "home.f_payroll_text": "Mishahara ya kila mwezi na makato, pamoja na stakabadhi ya malipo kila mfanyakazi anayosaini.",
    "home.f_reports": "Ripoti",
    "home.f_reports_text": "Mapato, gharama, faida, bidhaa zinazouzwa zaidi na thamani ya hifadhi, siku kwa siku na mwezi kwa mwezi.",
    "home.f_team": "Timu yako",
    "home.f_team_text": "Wafanyakazi wanapata njia yao ya kuingia na kuona tu kile nafasi yao inaruhusu.",
    "home.f_messages": "Ujumbe na tahadhari",
    "home.f_messages_text": "Ongea na timu yako ndani ya Higoverse, na upate taarifa za mauzo, faini na hifadhi ndogo papo hapo.",
    "home.cars_title": "Kwa wauzaji wa magari",
    "home.cars_sub": "Kila gari ni gari moja, linalofuatiliwa tangu linapofika hadi linapohamishwa.",
    "home.cars_1": "Ingiza magari mengi kwa mara moja (10 BYD Yuan Up, 20 Neta U Pro), kisha lipe kila moja namba yake ya chasisi na usajili.",
    "home.cars_2": "Magari yamepangwa kwa jina, yakionyesha yaliyopo, yanayosubiri kuhamishwa au yaliyouzwa.",
    "home.cars_3": "Malipo ya awali na salio kwa kila mnunuzi, na faini za barabarani zinazohifadhiwa na gari hadi linapohamishwa.",
    "home.cars_4": "Proforma za magari zenye chasisi, usajili na akaunti yako ya benki, tayari kuchapishwa.",
    "home.shops_title": "Kwa maduka",
    "home.shops_sub": "Jua ulicho nacho, kinachouzwa na unachopaswa kuagiza, bila kuhesabu kwa mkono.",
    "home.shops_1": "Hifadhi ndogo na iliyoisha inaonyeshwa kwanza, na kujaza kwa mbofyo mmoja.",
    "home.shops_2": "Manunuzi kutoka kwa wasambazaji yanaongezeka kwenye hifadhi yenyewe.",
    "home.shops_3": "Mauzo ya mkopo yanafuatiliwa kama madeni ya wateja hadi yalipwe.",
    "home.shops_4": "Picha, bei na faida kwa kila bidhaa, na kuingiza kwa Excel ili kuanza haraka.",
    "home.start_title": "Jinsi ya kuanza",
    "home.start_1": "Wasiliana nasi",
    "home.start_1_text": "Piga simu au andikia Higoverse na utueleze kuhusu biashara yako.",
    "home.start_2": "Tunakuandalia akaunti",
    "home.start_2_text": "Tunaunda biashara yako na njia yako ya kuingia, kwa duka au biashara ya magari.",
    "home.start_3": "Anza kurekodi",
    "home.start_3_text": "Ongeza bidhaa au magari yako, alika timu yako, na urekodi mauzo yako ya kwanza.",
    "home.privacy_line": "Rekodi zako ni za biashara yako pekee.",
    "home.privacy_link": "Sera ya faragha",
    "home.faq_title": "Maswali",
    "home.faq1_q": "Higoverse ni kwa ajili ya nani?",
    "home.faq1_a": "Maduka na biashara nchini Rwanda zinazonunua na kuuza bidhaa, na wauzaji wa magari wanaohitaji kufuatilia kila gari kwa chasisi na namba ya usajili.",
    "home.faq2_q": "Ninapataje akaunti?",
    "home.faq2_a": "Akaunti zinaundwa na Higoverse. Tupigie au utuandikie na tutaandaa biashara yako; kisha unaingia kwa barua pepe na nenosiri lako.",
    "home.faq3_q": "Wafanyakazi wangu wanaweza kuitumia?",
    "home.faq3_a": "Ndiyo. Mmiliki anaongeza wafanyakazi wenye njia yao ya kuingia, na kila mmoja anaona tu kile nafasi yake inaruhusu. Kwa wauzaji wa magari, wafanyakazi hawaoni faida wala gharama.",
    "home.faq4_q": "Inafanya kazi kwenye simu na kompyuta?",
    "home.faq4_a": "Ndiyo. Tumia tovuti kutoka kivinjari chochote, programu ya Android kwenye simu, au programu ya Windows kwenye kompyuta. Data yako ni ile ile kila mahali.",
    "home.faq5_q": "Inatumia lugha zipi?",
    "home.faq5_a": "Kiingereza, Kinyarwanda, Kifaransa, Kiswahili na Kichina. Kila mtu anachagua lugha yake.",
    "home.faq6_q": "Data ya biashara yangu ni ya faragha?",
    "home.faq6_a": "Ndiyo. Kila biashara inaona rekodi zake tu, na wafanyakazi kile nafasi zao zinaruhusu tu. Sera ya faragha inaeleza kinachohifadhiwa na kwa nini.",
    "home.faq_sub": "Majibu mafupi kuhusu akaunti, timu yako, vifaa vyako na data yako.",
    "home.faq_more_title": "Bado una swali?",
    "home.faq_more_text": "Tuulize moja kwa moja. Tunajibu kwenye WhatsApp, kwa simu na kwa barua pepe.",
    "home.faq7_q": "Je, naweza kuingiza bidhaa nilizo nazo tayari?",
    "home.faq7_a": "Ndiyo. Pakua kiolezo cha Excel kwenye ukurasa wa bidhaa, jaza bidhaa zako, kisha ingiza faili. Orodha pia zinaweza kutolewa kwenda Excel wakati wowote.",
    "home.faq8_q": "Mtanisaidia kuanza?",
    "home.faq8_a": "Ndiyo. Tunaandaa biashara yako pamoja nawe, na unaweza kutufikia kwenye WhatsApp, kwa simu au kwa barua pepe wakati wowote una swali.",
