    "home.start_1": "联系我们",
    "home.start_1_text": "致电或写信给 Higoverse，介绍您的业务。",
    "home.start_2": "我们为您开通账户",
    "home.start_2_text": "我们为您的商店或汽车经销业务创建企业和登录账号。",
    "home.start_3": "开始记录",
    "home.start_3_text": "添加商品或车辆，邀请团队，记录第一笔销售。",
    "home.privacy_line": "您的记录仅属于您的企业。",
    "home.privacy_link": "隐私政策",
    "home.faq_title": "常见问题",
    "home.faq1_q": "Higoverse 适合谁？",
    "home.faq1_a": "适合在卢旺达买卖商品的商店和企业，以及需要按车架号和车牌号跟踪每辆车的汽车经销商。",
    "home.faq2_q": "如何获得账户？",
    "home.faq2_a": "账户由 Higoverse 创建。致电或写信给我们，我们为您设置企业；之后您使用邮箱和密码登录。",
    "home.faq3_q": "员工可以使用吗？",
    "home.faq3_a": "可以。所有者为员工添加各自的登录账号，每人只能看到其角色允许的内容。在汽车经销商中，员工看不到利润和成本。",
    "home.faq4_q": "手机和电脑都能用吗？",
    "home.faq4_a": "可以。用任意浏览器访问网站，手机上使用 Android 应用，电脑上使用 Windows 应用。各处数据一致。",
    "home.faq5_q": "支持哪些语言？",
    "home.faq5_a": "英语、卢旺达语、法语、斯瓦希里语和中文，每个人可自选语言。",
    "home.faq6_q": "我的企业数据是私密的吗？",
    "home.faq6_a": "是的。每个企业只能看到自己的记录，员工只能看到其角色允许的内容。隐私政策说明了存储哪些数据及原因。",
    "home.faq_sub": "关于账户、团队、设备和数据的简短解答。",
    "home.faq_more_title": "还有其他问题？",
    "home.faq_more_text": "直接问我们。我们通过 WhatsApp、电话和电子邮件回复。",
    "home.faq7_q": "我可以导入已有的商品吗？",
    "home.faq7_a": "可以。在商品页面下载 Excel 模板，填入您的商品，然后导入文件。各类列表也可以随时导出为 Excel。",
    "home.faq8_q": "你们会帮我开始使用吗？",
    "home.faq8_a": "会的。我们与您一起设置您的企业；有任何问题，您都可以通过 WhatsApp、电话或电子邮件联系我们。",
